/* @autogenerated */
package net.civeira.phylax.common.crypto;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

@DisplayName("PasswordHasher")
class PasswordHasherUnitTest {
  /** Base64 of "saltsalt" (8 bytes). */
  private static final String SALT = "c2FsdHNhbHQ";
  /** Base64 of 16 zero bytes. */
  private static final String HASH = "AAAAAAAAAAAAAAAAAAAAAA";

  private final PasswordHasher hasher = new PasswordHasher();

  private static String stored(String m, String t, String p, String salt, String hash) {
    return "$argon2id$v=19$m=" + m + ",t=" + t + ",p=" + p + "$" + salt + "$" + hash;
  }

  @Test
  @DisplayName("Should reject null and malformed stored hashes")
  void shouldRejectNullAndMalformedHashes() {
    assertFalse(hasher.verify("secret", null), "null stored hash must not verify");
    assertFalse(hasher.verify("secret", "$2y$10$bcrypt"), "non argon2id format must not verify");
  }

  @ParameterizedTest(name = "{0}")
  @ValueSource(strings = {"m=4", "m=2000000", "t=0", "t=101", "p=0", "p=17", "salt", "hash"})
  @DisplayName("Should reject parameters outside the accepted ranges")
  void shouldRejectOutOfRangeParameters(String outOfRange) {
    // Arrange — a well formed hash with one parameter out of its range
    String m =
        "m=4".equals(outOfRange) ? "4" : "m=2000000".equals(outOfRange) ? "2000000" : "65536";
    String t = "t=0".equals(outOfRange) ? "0" : "t=101".equals(outOfRange) ? "101" : "4";
    String p = "p=0".equals(outOfRange) ? "0" : "p=17".equals(outOfRange) ? "17" : "1";
    String salt = "salt".equals(outOfRange) ? "c2FsdA" : SALT;
    String hash = "hash".equals(outOfRange) ? "AAAAAAAAAAA" : HASH;

    // Act / Assert — verification fails without deriving the key
    assertFalse(hasher.verify("secret", stored(m, t, p, salt, hash)));
  }

  @Test
  @DisplayName("Should reject hashes whose numbers or base64 cannot be decoded")
  void shouldRejectUndecodableHashes() {
    assertFalse(hasher.verify("secret", stored("99999999999", "4", "1", SALT, HASH)),
        "numeric overflow must be treated as an invalid hash");
    assertFalse(hasher.verify("secret", stored("65536", "4", "1", "A", HASH)),
        "invalid base64 must be treated as an invalid hash");
  }

  @Test
  @DisplayName("Should ask for rehash when the hash is missing, malformed or uses other parameters")
  void shouldDetectRehashNeed() {
    assertTrue(hasher.needsRehash(null));
    assertTrue(hasher.needsRehash("plain"));
    assertTrue(hasher.needsRehash(stored("32768", "4", "1", SALT, HASH)));
    assertTrue(hasher.needsRehash(stored("65536", "3", "1", SALT, HASH)));
    assertTrue(hasher.needsRehash(stored("65536", "4", "2", SALT, HASH)));
    assertFalse(hasher.needsRehash(stored("65536", "4", "1", SALT, HASH)));
  }

  @Test
  @DisplayName("Should support only argon2id hashes")
  void shouldSupportOnlyArgon2id() {
    assertFalse(PasswordHasher.isSupported(null));
    assertFalse(PasswordHasher.isSupported("$2y$10$bcrypt"));
    assertTrue(PasswordHasher.isSupported(stored("65536", "4", "1", SALT, HASH)));
  }
}
